from pathlib import Path
import hashlib,json
lane=Path(__file__).resolve().parent
records=json.loads((lane.parent/'extracted/data/reviewed-catalog.json').read_text(encoding='utf-8-sig'))
r=next(r for r in records if r['id']=='cross-clock-departure-injection')
statement=('Distinct original roots with certified same-transition absent-root relays inject into their endpoint old payload and original endpoint column, across all clocks in one fixed history. Every arising endpoint payload y satisfies y>=3; its charged-root count is at most the number of relay-eligible departure columns, hence at most y-2. For an arbitrary nonnegative payload y, the bound is max(0,y-2), with no arising endpoints when y<3.')
assumptions=r['assumptions']+['Every relay starts at a strict old-core host b<q-2, so q>=3; its finite exact leftward path ends at a rising column c<=q-3. Endpoint old payload y>=q>=3. Root absence is in the new retained prefix, and all row/source domains are as defined in the public relay supplement.']
oldstep='4. A rise cannot be COPY, so its old valuey≥q. Leftward relays from strict old-core hosts havec≤q−3≤y−3. For fixed y there are at most y−2 nonnegative such columns, proving the restricted count bound.'
assert oldstep in r['proofText']
newstep='4. A rise cannot be COPY, so its old value y>=q. The strict old-core starting host b<q-2 requires q>=3, and a leftward relay ends at 0<=c<=q-3<=y-3. Thus every arising endpoint payload has y>=3, and there are at most y-2 eligible columns for that payload. For arbitrary y>=0 use max(0,y-2); no endpoint with y<3 can arise. This is the restricted departure-resource count, not a bound on all value departures.'
patch={'scope':'New explicit endpoint-domain clarification discovered in renewed audit of the delivered ZIP. Earlier original-claim verdict is preserved; the literal statement is narrowed/totalized at the previously omitted y<3 boundary.','corrections':[{'id':r['id'],'old':{'statement':r['statement'],'assumptions':r['assumptions'],'proofText':r['proofText']},'fields':{'statement':statement,'assumptions':assumptions,'proofText':r['proofText'].replace(oldstep,newstep)},'changeType':'domain-clarification','mathematicalReason':'With no endpoints, the unguarded expression at y=1 could read 0<=-1. Arising endpoints have y>=q>=3; the nonnegative totalized bound retains exactly the proved resource count.','supplementPath':'papers/supplements/PRIVATE-HISTORY-AND-RELAY.md'}]}
shell=next(r for r in records if r['id']=='legacy-charged-shell-criterion')
oldparagraph=next(p for p in shell['proofText'].split('\n\n')if p.startswith('4.'))
newparagraph=('4. The published claim is the local Hall criterion in the specified finite charged-shell class. Increasing a child cap can only weaken the residual near/far indicators and enlarge the allowed support ranges; this gives the monotonicity used in the local normalization. No greatest-table or complete-search theorem is asserted here. Such a theorem would additionally require a fully defined update operator, finite admissible lag/rank box and paid boundary states. Numeric C460 obstruction/search counts are not inputs to this statement.')
patch['corrections'].append({'id':shell['id'],'old':{'proofText':shell['proofText']},'fields':{'proofText':shell['proofText'].replace(oldparagraph,newparagraph)},'changeType':'remove-extraneous-undefined-operator-claim','mathematicalReason':'The undefined T(A) and greatest-table pruning narration are unnecessary for the local Hall criterion; remove that ancillary assertion rather than implying an unprovided complete-search theorem.','supplementPath':'papers/supplements/FINITE-CERTIFICATE-INDUCTION.md'})
fresh=next(r for r in records if r['id']=='q-tight-fresh-permutations')
oldphrase='Small indices do not b or row the q>=3 terminal-capacity lemma.'
assert oldphrase in fresh['proofText']
patch['corrections'].append({'id':fresh['id'],'old':{'proofText':fresh['proofText']},'fields':{'proofText':fresh['proofText'].replace(oldphrase,'Small indices do not use the q>=3 terminal-capacity lemma outside its domain.')},'changeType':'editorial-clarification','mathematicalReason':'Repair a garbled English sentence without changing the small-index proof or hypotheses.','supplementPath':'papers/supplements/SOURCE-TIME-AND-TIGHTNESS.md'})
pellpatch=json.loads((lane.parent/'lean-semantics/pell-positive-compact-correction.json').read_text(encoding='utf-8'))
pell=next(r for r in records if r['id']==pellpatch['id'])
assert pellpatch['old']in pell['proofText']
patch['corrections'].append({'id':pell['id'],'old':{'proofText':pell['proofText']},'fields':{'proofText':pell['proofText'].replace(pellpatch['old'],pellpatch['replacement'])},'changeType':'auxiliary-sharpness-scope-clarification','mathematicalReason':pellpatch['reason'],'supplementPath':pellpatch['supplement'],'conclusionChanged':False})
patch['scope']='Exact old/new corrections from the renewed delivered-ZIP paper review: one explicit relay endpoint domain, one unnecessary undefined pruning operator removed, one garbled English sentence repaired, and integer-compatible inventory sharpness clarified. Earlier original-claim verdicts remain preserved; none of these clarifications discharges a canonical supplier.'
(lane/'CROSS-CLOCK-CORRECTION.json').write_text(json.dumps(patch,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('Exact old/new cross-clock patch written.')
